create or replace TABLE LDL_WAWI_PRODUCTION.CORE_DIM.T_FACT_INVOICE_KALKULATION_2 (
	WAWI_INSTANZ_KZL VARCHAR(3) NOT NULL COMMENT 'WaWi Instanz, T316_INVOICEHEAD.WAWI_INSTANZ_KZL (only in the consolidated layer)',
	INVOICE_ID NUMBER(38,0) NOT NULL COMMENT 'T316_INVOICEHEAD.C316_INVOICEID',
	RECORD_TYPE_ID NUMBER(38,0) NOT NULL COMMENT 'T316_INVOICEHEAD.C316_RECORDTYPE',
	GESELLSCHAFT_NR NUMBER(38,0) NOT NULL COMMENT 'T316_INVOICEHEAD.C316_WHNR',
	KRED_NR VARCHAR(100) NOT NULL COMMENT 'T316_INVOICEHEAD.C316_SUPPLIERNR - The invoice supplier_2 here can deviate from the incoming goods supplier.',
	WE_DATUM DATE NOT NULL COMMENT 'WEPOS.WEDATUM - join T316_INVOICEHEAD.C316_INVOICEID and WEPOS.RA_POSNR',
	WAEHRUNG_KBEZ VARCHAR(3) NOT NULL COMMENT 'WAEHRUNGSKNZ.WAEHRKBEZ - join T316_INVOICEHEAD.C316_CURRENCYCODE and WAEHRUNGSKNZ.WAEHRUNGSKNZ_2',
	AKZEPTIERTE_DIFFERENZ_EK_NETTO_WERT NUMBER(38,5) COMMENT 'T318_INVOICEDETWH.C318_DIFFVALUE - Akzeptierte Differenzen (RP011) EK Netto - Akzeptierte Differenzen RePrü',
	NICHT_PRUEFBARE_DIFFERENZ_EK_NETTO_WERT NUMBER(38,5) COMMENT 'T317 / T318 berechnet - Nicht prüfbare Positionen (RSH16) EK Netto in LW - Nicht prüfbare Positionen RePrü',
	ZU_KLAERENDE_DIFFERENZ_EK_NETTO_WERT NUMBER(38,5) COMMENT 'WEPOS_2 / T316 / T318 berechnet - Zu klärende Differenzen (RSH18) in EK Netto - Zu klärende Differenzen RePrü',
	ZU_KLAERENDE_DIFFERENZ_VK_NETTO_WERT NUMBER(38,5) COMMENT 'WEPOS_2 / T318 berechnet - Zu klärende Differenzen (RSH18) in VK_2 Netto - Zu klärende Differenzen RePrü',
	constraint PK_T_FACT_INVOICE_KALKULATION primary key (WAWI_INSTANZ_KZL, INVOICE_ID, RECORD_TYPE_ID)
)COMMENT='Faktentabelle auf Ebene Rechnungskopf für Lieferantenrechnungen.'
;